using FluentValidation;
namespace FintechApp.Requests.BeneficiaryOTP { public class UpdateBeneficiaryOTPRequest { public int BeneficiaryOTPID { get; set; } public string SenderMobile { get; set; } = string.Empty; public string OTP { get; set; } = string.Empty; public int SenderID { get; set; } public int BeneficiaryID { get; set; } public int UserID { get; set; } public bool IsOTPVerified { get; set; } } public class UpdateBeneficiaryOTPRequestValidator : AbstractValidator<UpdateBeneficiaryOTPRequest> { public UpdateBeneficiaryOTPRequestValidator() { RuleFor(x => x.BeneficiaryOTPID).GreaterThan(0); } } }
